// THE FINAL INTEGRATION (P2 closed end-to-end). A self-contained body bound by the shadow of its OWN active vacuum,
// on the real {3,4,3,4} coin. No external injection, the vacuum is self-generated by the create move (every empty
// line brings out a zero-momentum pair, a tone on a direction and its opposite). The tones propagate and annihilate
// head-on, the body excludes the vacuum (absorbs), and the open boundary absorbs (the bath). The decisive point, the
// create move makes ZERO-momentum pairs, so it CANNOT refill a momentum imbalance, only the body's absorption sets a
// net momentum, which points TOWARD the body (the tones that would pass through the body are absorbed, a shadow). So
// a self-contained body holds itself by the radiation pressure of its own vacuum, the restoring force that repairs a
// displaced piece, all reversible in the bulk (streaming is a bijection), the only irreversibility the body and the
// open boundary. Fully discrete, occupancy tones on the 24 directed slots, exact integer momentum, the true D4
// directions.
//
// Depth L2, the self-contained shadow self on {3,4,3,4}, the net momentum near a body in its OWN active vacuum points
// toward the body (the binding restoring force), with the no-body symmetric vacuum as the control.

import { experiment } from '@/test/scaffold/suite'
import { verdict } from '@/test/scaffold/verdict'
import { selfContainedShadowD4 } from '@/code/dynamics/shadow-pressure'

export default experiment({
  id: 'selves/self-contained-shadow-self',
  title: 'a self-contained body binds itself by the shadow of its OWN active vacuum on the 24-direction D4 coin',
  category: 'selves',
  substrates: ['d4'],
  depth: 'L2',
  paper: true,
  run() {
    const base = { side: 14, beats: 56, bodyLoX: 3, bodyHiX: 6, testX: 9 }
    const withBody = selfContainedShadowD4({ ...base, body: true })
    const noBody = selfContainedShadowD4({ ...base, body: false })

    // the net momentum near the body points toward it (the restoring force), the no-body vacuum is symmetric.
    const binds = withBody < -0.5
    const controlFlat = Math.abs(noBody) < 0.02
    const ok = binds && controlFlat

    return verdict({
      status: ok ? 'pass' : 'fail',
      claim:
        'a self-contained body bound by the shadow of its OWN active vacuum, on the real {3,4,3,4} coin, the vacuum is self-generated by the create move (zero-momentum pairs on every empty line), the tones propagate and annihilate, the body excludes the vacuum and the open boundary absorbs, and because the create move makes zero-momentum pairs it cannot refill a momentum imbalance, so only the body absorption sets a net momentum, which points TOWARD the body (a shadow of the tones it absorbed) = the restoring force that repairs a displaced piece, while with no body the vacuum is symmetric and the net momentum is zero, the bulk streaming is an exact reversible bijection and the only irreversibility is the body and the open boundary (binding-by-radiation), fully discrete on the 24 directed slots with exact integer momentum',
      metrics: {
        netXmomentumWithBodyTimes1000: Math.round(withBody * 1000),
        netXmomentumNoBodyTimes1000: Math.round(noBody * 1000),
        binds: binds ? 1 : 0,
        controlFlat: controlFlat ? 1 : 0,
        side: base.side,
        directions: 24,
      },
      control: { netXmomentumNoBodyTimes1000: Math.round(noBody * 1000) },
      notes:
        'the final integration, P2 closed end-to-end. A self-contained body in its OWN self-generated active vacuum (the create move) casts a shadow whose radiation pressure points toward the body (the binding restoring force), measured in the true D4 root vectors, no external injection, control exactly zero. The create move makes zero-momentum pairs so it cannot wash out the imbalance, only the body absorption sets the net momentum. Reversible bulk, irreversibility only at the body and bath. Fully discrete on the 24-cell coin',
    })
  },
})
